import openpyxl
wb = openpyxl.load_workbook('data/gaia/raw/5cfb274c-0207-4aa7-9575-6ac0bd95d9b2.xlsx')
ws = wb.active

green_color = 'FF00FF00'
green_cells = set()
grid = {}

for row in ws.iter_rows():
    for cell in row:
        fill = cell.fill
        if fill and fill.fgColor:
            color = fill.fgColor.rgb if fill.fgColor.type == 'rgb' else None
            grid[(cell.row, cell.column)] = color
            if color == green_color:
                green_cells.add((cell.row, cell.column))

print('Green cells count:', len(green_cells))
print('Green cells:', sorted(green_cells))

rows = sorted(set(r for r,c in green_cells))
cols = sorted(set(c for r,c in green_cells))
print('Row range:', min(rows), '-', max(rows))
print('Col range:', min(cols), '-', max(cols))

print()
print('Grid visualization:')
for r in range(1, ws.max_row+1):
    row_str = ''
    for c in range(1, ws.max_column+1):
        color = grid.get((r,c))
        if color == 'FF00FF00':
            row_str += 'G'
        elif color == 'FF4A86E8':
            row_str += 'B'
        elif color == 'FF9900FF':
            row_str += 'P'
        elif color == 'FFFF0000':
            row_str += 'R'
        elif color == 'FFFFFF00':
            row_str += 'Y'
        elif color == 'FFFF9900':
            row_str += 'O'
        else:
            row_str += '.'
    print(f'Row {r:2d}: {row_str}')

print()
print('Checking Hamiltonian cycle on green cells...')

def get_neighbors(r, c, cell_set):
    neighbors = []
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        if (r+dr, c+dc) in cell_set:
            neighbors.append((r+dr, c+dc))
    return neighbors

adj = {cell: get_neighbors(cell[0], cell[1], green_cells) for cell in green_cells}
print('Adjacency (degree of each node):')
degree_counts = {}
for cell, neighbors in sorted(adj.items()):
    d = len(neighbors)
    degree_counts[d] = degree_counts.get(d, 0) + 1

print('Degree distribution:', degree_counts)

all_degree_2_or_more = all(len(v) >= 2 for v in adj.values())
print('All nodes have degree >= 2:', all_degree_2_or_more)

if not all_degree_2_or_more:
    print('Nodes with degree < 2:')
    for cell, neighbors in sorted(adj.items()):
        if len(neighbors) < 2:
            print(f'  {cell}: degree {len(neighbors)}')

import sys

def hamiltonian_cycle(adj, start):
    n = len(adj)
    path = [start]
    visited = {start}

    def backtrack():
        if len(path) == n:
            if path[0] in adj[path[-1]]:
                return True
            return False

        current = path[-1]
        for neighbor in adj[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                path.append(neighbor)
                if backtrack():
                    return True
                path.pop()
                visited.remove(neighbor)
        return False

    return backtrack()

start = sorted(green_cells)[0]
print(f'Starting from {start}...')
result = hamiltonian_cycle(adj, start)
print('Hamiltonian cycle exists:', result)
